# Generated by build.py from recipe.yml for recipe http-move-a-client-to-https. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'during', '--cert', 'server.pem', '--key', 'server.key', '--trace-ascii', 'during.log', 'http://127.0.0.1:8080/', 'https://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --proto =https --cacert server.pem https://127.0.0.1:8081/hello.txt } finally { Stop-Process $server0 }
